(function(window,document){'use strict';function markVisible(){var height=window.innerHeight||document.documentElement.clientHeight;Array.prototype.forEach.call(document.querySelectorAll('[data-aos]:not(.aos-init)'),function(element){var box=element.getBoundingClientRect();if(box.bottom>0&&box.top<height){element.classList.add('aos-animate')}})}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',markVisible)}else{markVisible()}})(window,document)
